// 生前真实提名与本人答复共用原权源预览；没有任何隐式Office、军令或财产交割。
#include "political_successor_round_detail.hpp"
namespace hanmo::resident {namespace {
// typed命令逐字段比较，不把同一报价换成另一候选或任职epoch。
bool same(const PoliticalSuccessorRoundNominationCommand& a,const PoliticalSuccessorRoundNominationCommand& b){if(a.index()!=b.index())return false;return std::visit([&](const auto& lhs){using T=std::decay_t<decltype(lhs)>;const auto& rhs=std::get<T>(b);if constexpr(std::is_same_v<T,PoliticalAnswerNextSuccession>)return lhs.nomination_fact_id==rhs.nomination_fact_id&&lhs.accept==rhs.accept;else{const auto& x=lhs.authority;const auto& y=rhs.authority;if(std::tie(x.organization_id,x.office_id,x.actor_id,x.authority_epoch)!=std::tie(y.organization_id,y.office_id,y.actor_id,y.authority_epoch))return false;if constexpr(std::is_same_v<T,PoliticalNominateNextSuccessor>)return std::tie(lhs.policy_id,lhs.candidate_actor_id,lhs.expected_office_epoch,lhs.expected_head_source_fact_id)==std::tie(rhs.policy_id,rhs.candidate_actor_id,rhs.expected_office_epoch,rhs.expected_head_source_fact_id);else return lhs.nomination_fact_id==rhs.nomination_fact_id;}},a);}
// 新任期签发须真实完成原就任并仍在位，作者副手代办不自动取得正式提名权。
Status issuer(const PoliticalSuccessorRoundContext& x,const PoliticalSuccessorRoundPolicy& p,const ActingAuthority& a,const StableId& kind,const StableId& source){const auto* original=x.heads.succession_catalog.policies.find(p.succession_policy_id);if(!original)return common_failure("PoliticalSuccessorRoundPolicyUnknown",p.id);auto valid=successor_round_detail::head(x,p,a.actor_id,a.authority_epoch,source,{},x.common.tick(),{});if(!valid.ok)return valid;if(a.office_id!=original->leader_office_id||a.organization_id!=original->organization_id)return common_failure("PoliticalSuccessorRoundOriginalOfficeRequired",p.id);valid=successor_round_detail::member_now(x,*original,a.actor_id);if(!valid.ok)return valid;auto authority=check_authority(x.common,x.organizations,x.organization_catalog,a,kind,{ScopeRef::Kind::site,original->seat_place_id},0);if(!authority.ok)return {false,{},authority.error};return successor_round_detail::grant(x,p,*original,p.nomination_grant_id,kind,x.common.tick());}
}
Outcome<PoliticalSuccessorRoundNominationQuote> preview_political_successor_round_nomination(const PoliticalSuccessorRoundContext& x,const StableId& actor,const PoliticalSuccessorRoundNominationCommand& command){
 auto fail=[](const Status& s){return Outcome<PoliticalSuccessorRoundNominationQuote>{false,{},s.error};};
 if(actor!=x.common.state().metadata.player_actor_id)return fail(common_failure("PoliticalSuccessorRoundPlayerRequired"));
 if(!x.player_before||!x.seat)return fail(common_failure("PoliticalSuccessorRoundHistoricalReadersRequired"));
 auto valid=validate_political_successor_round_nominations(x);if(!valid.ok)return fail(valid);
 auto checked=std::visit([&](const auto& c)->Status{using T=std::decay_t<decltype(c)>;const PoliticalSuccessorRoundNomination* old=nullptr;const PoliticalSuccessorRoundPolicy* p=nullptr;
  if constexpr(std::is_same_v<T,PoliticalNominateNextSuccessor>){if(x.state.nominations.size()>=4096)return common_failure("PoliticalSuccessorRoundHistoryCapacity");p=x.catalog.policies.find(c.policy_id);if(c.authority.actor_id!=actor||!p)return common_failure("PoliticalSuccessorRoundPolicyUnknown");}
  else{if constexpr(std::is_same_v<T,PoliticalAnswerNextSuccession>){if(x.state.answers.size()>=8192)return common_failure("PoliticalSuccessorRoundHistoryCapacity");}else if(x.state.withdrawals.size()>=4096)return common_failure("PoliticalSuccessorRoundHistoryCapacity");old=x.state.nominations.find(c.nomination_fact_id);if(!old||(std::is_same_v<T,PoliticalAnswerNextSuccession>?old->candidate_actor_id:old->issuer_actor_id)!=actor)return common_failure("PoliticalSuccessorRoundNotKnown");p=x.catalog.policies.find(old->policy_id);if(!p)return common_failure("PoliticalSuccessorRoundPolicyUnknown");if(successor_round_detail::acceded(x.state,old->id))return common_failure("PoliticalSuccessorRoundAlreadyAcceded",old->id);if(successor_round_detail::closed(x.state,old->id))return common_failure("PoliticalSuccessorRoundAlreadyClosed",old->id);}
  const auto* original=x.heads.succession_catalog.policies.find(p->succession_policy_id);if(!original)return common_failure("PoliticalSuccessorRoundPolicyUnknown");
  auto v=successor_round_detail::contact(x,*original,actor);if(!v.ok)return v;v=x.seat(*original,x.common.tick(),{});if(!v.ok)return v;
  if constexpr(std::is_same_v<T,PoliticalNominateNextSuccessor>){
   if(c.candidate_actor_id==actor)return common_failure("PoliticalSuccessorRoundDistinctCandidateRequired");v=issuer(x,*p,c.authority,political_successor_round_nominate_command,c.expected_head_source_fact_id);if(!v.ok)return v;if(c.expected_office_epoch!=c.authority.authority_epoch)return common_failure("PoliticalSuccessorRoundOfficeVersionChanged");
   v=successor_round_detail::contact(x,*original,c.candidate_actor_id);if(!v.ok)return v;
   for(const auto& id:{actor,c.candidate_actor_id}){v=growth_independent_office_age(x.common,id);if(!v.ok)return v;v=successor_round_detail::member_now(x,*original,id);if(!v.ok)return v;}
   if(x.common.tick()>std::numeric_limits<Integer>::max()-p->response_ticks)return common_failure("PoliticalSuccessorRoundDeadlineOverflow");
   for(const auto& row:x.state.nominations.rows())if(row.second.policy_id==p->id&&row.second.office_epoch==c.expected_office_epoch&&!successor_round_detail::acceded(x.state,row.first)&&!successor_round_detail::closed(x.state,row.first)&&(successor_round_detail::accepted(x.state,row.first)||x.common.tick()<row.second.response_until))return common_failure("PoliticalSuccessorRoundNominationAlreadyPending");
  }else if constexpr(std::is_same_v<T,PoliticalAnswerNextSuccession>){
   const auto* prior=successor_round_detail::accepted(x.state,old->id);if(c.accept&&prior)return common_failure("PoliticalSuccessorRoundAlreadyAccepted");if(!prior&&x.common.tick()>=old->response_until)return common_failure("PoliticalSuccessorRoundNominationExpired");
   if(c.accept){v=successor_round_detail::contact(x,*original,old->issuer_actor_id);if(!v.ok)return v;v=successor_round_detail::member_now(x,*original,old->issuer_actor_id);if(!v.ok)return v;v=successor_round_detail::head(x,*p,old->issuer_actor_id,old->office_epoch,old->head_source_fact_id,old->head_office_change_fact_id,x.common.tick(),{});if(!v.ok)return v;v=successor_round_detail::grant(x,*p,*original,old->grant_id,political_successor_round_nominate_command,x.common.tick());if(!v.ok)return v;v=growth_independent_office_age(x.common,actor);if(!v.ok)return v;v=successor_round_detail::member_now(x,*original,actor);if(!v.ok)return v;}
  }else{if(c.authority.actor_id!=actor||c.authority.authority_epoch!=old->office_epoch)return common_failure("PoliticalSuccessorRoundOriginalLeaderRequired");v=issuer(x,*p,c.authority,political_successor_round_withdraw_command,old->head_source_fact_id);if(!v.ok)return v;}
  return common_success();
 },command);return checked.ok?Outcome<PoliticalSuccessorRoundNominationQuote>{true,{x.common.state().identity,actor,command},{}}:fail(checked);
}
// 原候选负责回滚；该writer只追加明确意愿，不产生正式就任或默认代理授权。
Outcome<StableId> apply_political_successor_round_nomination_in_candidate(CommonStore& common,PoliticalSuccessorRoundState& state,const PoliticalSuccessorRoundContext& x,const StableId& actor,const PoliticalSuccessorRoundNominationCommand& command,const PoliticalSuccessorRoundNominationQuote& quote){
 const auto& a=common.state().identity;const auto& b=quote.identity;if(&common!=&x.common||&state!=&x.state||quote.actor_id!=actor||!same(command,quote.command)||std::tie(a.world_id,a.execution_epoch,a.revision,a.tick)!=std::tie(b.world_id,b.execution_epoch,b.revision,b.tick))return {false,{},common_failure("StalePoliticalSuccessorRoundQuote").error};auto valid=preview_political_successor_round_nomination(x,actor,command);if(!valid.ok)return {false,{},valid.error};
 auto next=state;auto result=std::visit([&](const auto& c)->Outcome<StableId>{using T=std::decay_t<decltype(c)>;StableId prefix,kind;if constexpr(std::is_same_v<T,PoliticalNominateNextSuccessor>){prefix="political_successor_round_nomination";kind="political_successor_round_nominated";}else if constexpr(std::is_same_v<T,PoliticalAnswerNextSuccession>){prefix=c.accept?"political_successor_round_acceptance":"political_successor_round_decline";kind=c.accept?"political_successor_round_accepted":"political_successor_round_declined";}else{prefix="political_successor_round_withdrawal";kind="political_successor_round_withdrawn";}auto id=common.next_id(prefix);if(!id.ok)return id;auto head=common.append_fact({id.value,kind,political_successor_rounds_domain});if(!head.ok)return {false,{},head.error};
  if constexpr(std::is_same_v<T,PoliticalNominateNextSuccessor>){const auto& p=*x.catalog.policies.find(c.policy_id);PoliticalSuccessorRoundNomination row;row.id=id.value;row.policy_id=p.id;const auto& original=*x.heads.succession_catalog.policies.find(p.succession_policy_id);row.organization_id=original.organization_id;row.office_id=original.leader_office_id;auto source=read_political_successor_round_head(x.heads,x.catalog,state,p.id);if(!source.ok||!source.value)return {false,{},source.ok?common_failure("PoliticalSuccessorRoundHeadChanged").error:source.error};row.head_source_fact_id=source.value->source_fact_id;row.head_office_change_fact_id=source.value->office_change_fact_id;row.issuer_actor_id=actor;row.candidate_actor_id=c.candidate_actor_id;row.grant_id=p.nomination_grant_id;row.office_epoch=c.authority.authority_epoch;row.issued_tick=common.tick();row.response_until=common.tick()+p.response_ticks;if(!next.nominations.insert(row.id,row))return {false,{},common_failure("DuplicatePoliticalSuccessorRoundSource").error};}
  else if constexpr(std::is_same_v<T,PoliticalAnswerNextSuccession>){PoliticalSuccessorRoundAnswer row;row.id=id.value;row.nomination_fact_id=c.nomination_fact_id;row.actor_id=actor;row.tick=common.tick();row.accepted=c.accept;if(const auto* prior=successor_round_detail::accepted(state,c.nomination_fact_id))row.previous_acceptance_fact_id=prior->id;if(!next.answers.insert(row.id,row))return {false,{},common_failure("DuplicatePoliticalSuccessorRoundSource").error};}
  else{const auto& nomination=*state.nominations.find(c.nomination_fact_id);PoliticalSuccessorRoundWithdrawal row;row.id=id.value;row.nomination_fact_id=nomination.id;row.actor_id=actor;row.grant_id=nomination.grant_id;row.office_epoch=c.authority.authority_epoch;row.tick=common.tick();if(!next.withdrawals.insert(row.id,row))return {false,{},common_failure("DuplicatePoliticalSuccessorRoundSource").error};}return id;
 },command);if(result.ok)state=std::move(next);return result;
}
}
